<div class="activity-list"><?php foreach (array_slice($activities, 0, $compact ? 3 : 30) as $a): ?><div class="activity-item"><span class="activity-icon <?= str_contains($a['action'], 'Résolue') ? 'done' : '' ?>"><?= icon(str_contains($a['action'], 'Résolue') ? 'check' : 'file') ?></span><div><strong><?= e($a['action']) ?></strong><p><?php if ($a['report_id']): ?><a href="<?= e(url('report', ['id'=>$a['report_id']])) ?>"><?= e(report_ref($a['report_id'])) ?><?php if (!$compact): ?> · <?= e($a['title']) ?><?php endif ?></a> <span>·</span> <?php endif ?><?= e($a['name']) ?></p></div><time datetime="<?= e($a['created_at']) ?>"><?= date_fr($a['created_at'], !$compact) ?></time></div><?php endforeach ?><?php if (!$activities): ?><div class="empty-state"><p>Les prochaines actions apparaîtront ici.</p></div><?php endif ?></div>
